import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
        except StopIteration:
            break

        adj = [set() for _ in range(N + 1)]
        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            if u < v:
                adj[u].add(v)

        A = []
        possible = True

        for i in range(N):
            targets = adj[i]
            if not targets:
                possible = False
                break

            min_target = min(targets)

            if min_target != i + 1:
                possible = False
                break

            required_edges = set()
            for t in targets:
                if t > i + 1:
                    required_edges.add(t)

            if min_target not in targets:
                possible = False
                break

            A.append(min_target)

            for t in required_edges:
                if t not in adj[i + 1]:
                    possible = False
                    break
            if not possible:
                break

        if not possible:
            print("-1")
        else:
            print(" ".join(map(str, A)))

if __name__ == "__main__":
    solve()
